package io.ahad.rechnungflow.testing;
import io.ahad.rechnungflow.core.*;import io.ahad.rechnungflow.workflow.*;
import java.util.*;import java.util.concurrent.atomic.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.time.*;import com.sun.net.httpserver.*;
import static io.ahad.rechnungflow.testing.TestKit.*;
public final class OutboxTest {
    @FunctionalInterface interface Case{void run(Fixtures f)throws Exception;}
    static void test(TestKit t,String name,Case c){t.test(name,()->{try(Fixtures f=new Fixtures(true,Fixtures.stub("PASS"))){c.run(f);}});}
    static String id(Map<String,Object>m){return Values.text(m,"id");}
    static Map<String,Object> job(Fixtures f,String id){return f.store.read(s->Json.object(Store.table(s,"jobs").get(id)));}
    static AccountingClient client(String status){return (key,p)->new AccountingClient.Delivery(status,status.equals("DELIVERED")?"receipt-123":"","test-code");}
    public static void main(String[]args)throws Exception{
        TestKit t=new TestKit("outbox");
        t.test("DEMO uses ledger without calling external accounting",()->{try(Fixtures f=new Fixtures()){String id=f.approved("01-ubl-office.xml"),j=id(f.queue(id));AtomicInteger calls=new AtomicInteger();var out=new OutboxService(f.store,f.service,(k,p)->{calls.incrementAndGet();throw new IllegalStateException();});yes(out.tick());eq("EXPORTED",Values.text(f.get(id),"stage"));eq("DELIVERED",Values.text(job(f,j),"status"));eq(0,calls.get());eq(1,f.store.read(s->Store.table(s,"sandbox").size()));yes(!out.tick());}});
        test(t,"Delivered acknowledgement updates invoice and job",f->{String id=f.approved("01-ubl-office.xml"),j=id(f.queue(id));var out=new OutboxService(f.store,f.service,client("DELIVERED"));yes(out.tick());eq("DELIVERED",Values.text(job(f,j),"status"));eq("EXPORTED",Values.text(f.get(id),"stage"));});
        test(t,"Empty queue produces no delivery",f->yes(!new OutboxService(f.store,f.service,client("DELIVERED")).tick()));
        test(t,"Ambiguous result is never automatically repeated",f->{String id=f.approved("01-ubl-office.xml"),j=id(f.queue(id));AtomicInteger count=new AtomicInteger();var out=new OutboxService(f.store,f.service,(k,p)->{count.incrementAndGet();return new AccountingClient.Delivery("UNKNOWN","","timeout");});out.tick();out.tick();eq(1,count.get());eq("UNKNOWN",Values.text(job(f,j),"status"));eq("EXPORT_PENDING",Values.text(f.get(id),"stage"));});
        test(t,"Unexpected adapter exception becomes UNKNOWN",f->{String id=f.approved("01-ubl-office.xml"),j=id(f.queue(id));new OutboxService(f.store,f.service,(k,p)->{throw new IllegalStateException("adapter failed");}).tick();eq("UNKNOWN",Values.text(job(f,j),"status"));});
        test(t,"Missing receipt cannot be treated as delivery",f->{String id=f.approved("01-ubl-office.xml"),j=id(f.queue(id));new OutboxService(f.store,f.service,(k,p)->new AccountingClient.Delivery("DELIVERED","","" )).tick();eq("UNKNOWN",Values.text(job(f,j),"status"));});
        test(t,"Unknown adapter result fails conservatively",f->{String id=f.approved("01-ubl-office.xml"),j=id(f.queue(id));new OutboxService(f.store,f.service,(k,p)->new AccountingClient.Delivery("SUCCESS","abc","" )).tick();eq("UNKNOWN",Values.text(job(f,j),"status"));});
        test(t,"Unconfigured accounting is BLOCKED",f->{String id=f.approved("01-ubl-office.xml"),j=id(f.queue(id));new OutboxService(f.store,f.service,AccountingClient.unavailable()).tick();eq("BLOCKED",Values.text(job(f,j),"status"));});
        test(t,"Retryable rejection schedules bounded retry",f->{String id=f.approved("01-ubl-office.xml"),j=id(f.queue(id));var out=new OutboxService(f.store,f.service,client("RETRY"));out.tick();eq("PENDING",Values.text(job(f,j),"status"));yes(Json.number(job(f,j),"nextAttemptAt",0)>System.currentTimeMillis());yes(!out.tick());});
        test(t,"Fifth retryable attempt stops at FAILED",f->{String id=f.approved("01-ubl-office.xml"),j=id(f.queue(id));var out=new OutboxService(f.store,f.service,client("RETRY"));for(int x=0;x<5;x++){f.store.write(s->{Json.object(Store.table(s,"jobs").get(j)).put("nextAttemptAt",0);return null;});out.tick();}eq("FAILED",Values.text(job(f,j),"status"));eq(5,Json.integer(job(f,j),"attempts",0));});
        test(t,"Restart marks in-flight work UNKNOWN",f->{String id=f.approved("01-ubl-office.xml"),j=id(f.queue(id));f.store.write(s->{Json.object(Store.table(s,"jobs").get(j)).put("status","IN_FLIGHT");return null;});new OutboxService(f.store,f.service,client("DELIVERED")).recover();eq("UNKNOWN",Values.text(job(f,j),"status"));});
        test(t,"Restart leaves pending work pending",f->{String id=f.approved("01-ubl-office.xml"),j=id(f.queue(id));new OutboxService(f.store,f.service,client("DELIVERED")).recover();eq("PENDING",Values.text(job(f,j),"status"));});
        test(t,"Known-not-delivered resolution permits explicit retry",f->{String id=f.approved("01-ubl-office.xml"),j=id(f.queue(id));var out=new OutboxService(f.store,f.service,client("UNKNOWN"));out.tick();out.reconcile(f.a("finance"),j,Values.map("decision","CONFIRM_NOT_DELIVERED","reason","Destination ledger checked"));eq("PENDING",Values.text(job(f,j),"status"));});
        test(t,"Confirmed destination receipt resolves UNKNOWN",f->{String id=f.approved("01-ubl-office.xml"),j=id(f.queue(id));var out=new OutboxService(f.store,f.service,client("UNKNOWN"));out.tick();out.reconcile(f.a("finance"),j,Values.map("decision","CONFIRM_DELIVERED","reason","Destination ledger checked","receipt","ACCOUNTING-123"));eq("EXPORTED",Values.text(f.get(id),"stage"));eq("ACCOUNTING-123",Values.text(job(f,j),"receipt"));});
        test(t,"Reconciliation needs receipt",f->{String id=f.approved("01-ubl-office.xml"),j=id(f.queue(id));var out=new OutboxService(f.store,f.service,client("UNKNOWN"));out.tick();error("INVALID_INPUT",()->out.reconcile(f.a("finance"),j,Values.map("decision","CONFIRM_DELIVERED","reason","Check")));});
        test(t,"Reconciliation requires finance authorization",f->{String id=f.approved("01-ubl-office.xml"),j=id(f.queue(id));var out=new OutboxService(f.store,f.service,client("UNKNOWN"));out.tick();error("FORBIDDEN",()->out.reconcile(f.a("auditor"),j,Values.map("decision","CONFIRM_NOT_DELIVERED","reason","Check")));});
        test(t,"Delivered work cannot be reset via reconciliation",f->{String id=f.approved("01-ubl-office.xml"),j=id(f.queue(id));var out=new OutboxService(f.store,f.service,client("DELIVERED"));out.tick();error("INVALID_TRANSITION",()->out.reconcile(f.a("finance"),j,Values.map("decision","CONFIRM_NOT_DELIVERED","reason","Check")));});
        test(t,"New duplicate before delivery blocks destination call",f->{String id=f.approved("01-ubl-office.xml"),j=id(f.queue(id));f.intakeBytes(Fixtures.changed("01-ubl-office.xml","Fictional","Different fictional"),f.a("intake"));AtomicInteger calls=new AtomicInteger();var out=new OutboxService(f.store,f.service,(k,p)->{calls.incrementAndGet();return new AccountingClient.Delivery("DELIVERED","r","");});out.tick();eq(0,calls.get());eq("BLOCKED",Values.text(job(f,j),"status"));});
        test(t,"Job listing omits accounting payload",f->{String id=f.approved("01-ubl-office.xml");f.queue(id);yes(!Json.object(new OutboxService(f.store,f.service,client("DELIVERED")).jobs(f.a("auditor")).getFirst()).containsKey("payload"));});
        test(t,"External idempotency key stable across attempts",f->{String id=f.approved("01-ubl-office.xml"),j=id(f.queue(id));var keys=new ArrayList<String>();var out=new OutboxService(f.store,f.service,(k,p)->{keys.add(k);return new AccountingClient.Delivery("RETRY","","test");});out.tick();f.store.write(s->{Json.object(Store.table(s,"jobs").get(j)).put("nextAttemptAt",0);return null;});out.tick();eq(2,keys.size());eq(keys.getFirst(),keys.getLast());});
        for(String uri:List.of("http://example.com/api","file:///etc/passwd","ftp://example.com","https://user:pass@example.com/","https://example.com/#fragment"))
            t.test("Accounting destination rejects "+uri,()->error("ACCOUNTING_URL_INVALID",()->new HttpAccountingClient(URI.create(uri),"",Duration.ofSeconds(1),false,false)));
        t.test("Header injection token denied",()->error("INVALID_CONFIGURATION",()->new HttpAccountingClient(URI.create("https://example.com"),"x\r\ny",Duration.ofSeconds(1),false,false)));
        try(Loopback server=new Loopback()){
            for(int status:List.of(200,201,204,400,401,403,404,408,429,500,503,307))t.test("HTTP accounting status "+status,()->{
                var c=server.client("/status/"+status,false,1000);String expected=status==200||status==201?"DELIVERED":Set.of(400,401,403,404).contains(status)?"FAILED":"UNKNOWN";
                eq(expected,c.deliver("fixed-key-123",Values.map("invoiceId","inv-123")).outcome());});
            t.test("Idempotency-attested 429 is retryable",()->eq("RETRY",server.client("/status/429",true,1000).deliver("key",Values.map("invoiceId","inv-123")).outcome()));
            t.test("Idempotency-attested 503 is retryable",()->eq("RETRY",server.client("/status/503",true,1000).deliver("key",Values.map("invoiceId","inv-123")).outcome()));
            t.test("Malformed acknowledgement remains UNKNOWN",()->eq("UNKNOWN",server.client("/malformed",false,1000).deliver("key",Values.map("invoiceId","inv-123")).outcome()));
            t.test("Acknowledgement cannot name another invoice",()->eq("UNKNOWN",server.client("/wrong-id",false,1000).deliver("key",Values.map("invoiceId","inv-123")).outcome()));
            t.test("Oversized response bounded",()->eq("UNKNOWN",server.client("/huge",false,1000).deliver("key",Values.map("invoiceId","inv-123")).outcome()));
            t.test("Timeout never pretends destination rolled back",()->{long start=System.nanoTime();eq("UNKNOWN",server.client("/slow",false,150).deliver("key",Values.map("invoiceId","inv-123")).outcome());yes((System.nanoTime()-start)/1_000_000<3000);});
            t.test("Idempotency header delivered to destination",()->{server.client("/status/200",false,1000).deliver("stable-header",Values.map("invoiceId","inv-123"));eq("stable-header",server.lastKey);});
        }
        t.finish("build/test-results/outbox.xml");
    }
    static final class Loopback implements AutoCloseable{
        final HttpServer server;final java.util.concurrent.ExecutorService executor=java.util.concurrent.Executors.newVirtualThreadPerTaskExecutor();volatile String lastKey;
        Loopback()throws Exception{server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.setExecutor(executor);server.createContext("/",e->{try{lastKey=e.getRequestHeaders().getFirst("Idempotency-Key");e.getRequestBody().readAllBytes();String p=e.getRequestURI().getPath();int status=p.startsWith("/status/")?Integer.parseInt(p.substring(8)):200;String body=p.equals("/malformed")?"not json":p.equals("/wrong-id")?"{\"invoiceId\":\"other\",\"receiptId\":\"r\"}":p.equals("/huge")?"x".repeat(70_000):"{\"invoiceId\":\"inv-123\",\"receiptId\":\"r-123\"}";if(p.equals("/slow"))try{Thread.sleep(1000);}catch(InterruptedException x){Thread.currentThread().interrupt();}byte[] b=body.getBytes(StandardCharsets.UTF_8);if(status==307)e.getResponseHeaders().set("Location","/status/200");e.sendResponseHeaders(status,status==204?-1:b.length);if(status!=204)e.getResponseBody().write(b);}catch(Exception ignored){}finally{e.close();}});server.start();}
        HttpAccountingClient client(String p,boolean idempotent,long timeout){return new HttpAccountingClient(URI.create("http://127.0.0.1:"+server.getAddress().getPort()+p),"fixture-token",Duration.ofMillis(timeout),idempotent,true);}
        public void close(){server.stop(0);executor.shutdownNow();}
    }
}
